package com.example.analytics; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="click_events") public class ClickEvent {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String code; @Column(length=2048) public String referrer; public Instant clickedAt; public ClickEvent(){} public ClickEvent(String c,String r,Instant t){code=c;referrer=r;clickedAt=t;}}